// План: specs/disputes.md, блок 2. Кейсы: .qa/tests/disputes/DSP-003…006, DSP-008.
// Несколько ролей: клиент (0500000004, «יונתן לוי») и נותן שירות (0500000005, «שירה כהן»), у каждого своё окно.
// Создаёт сделку QA-AUTO-… и спор → не @prod-safe. Один прогон (@android), без повторов — чтобы не плодить сделки.
import { test, expect } from '../../fixtures';
import { getEscrowDeal, openAiDispute, openTab, waitWithReload, historyEntries, TODAY_TIME } from './helpers';

test.describe.configure({ mode: 'serial', retries: 0 });

let dealId = '';

test.describe('מחלוקות — גישור AI', () => {
  test('לשונית מחלוקת (AI, ממתין לצד השני): אין כפתור ללא פעולה @android #7be825aa', async ({ asUser }) => {
    const client = await asUser('client');
    const provider = await asUser('provider');
    dealId = (await getEscrowDeal(client, provider, 'AI')).id;

    await openAiDispute(client, dealId);
    await client.goto(`/deals/${dealId}?tab=dispute`);

    for (const pass of ['open', 'after reload']) {
      if (pass === 'after reload') await client.reload();
      await expect(client.getByText('מחלוקת עם גישור AI').first(), pass).toBeVisible();
      await expect(client.getByText('ממתין לאישור הצד השני'), pass).toBeVisible();
      await expect(client.getByText('פרטי המחלוקת'), pass).toBeVisible();
      // #7be825aa «מה רצוי»: нет кнопки без действия, пока нет предложения — только чат.
      await expect(client.getByRole('button', { name: 'צפייה במחלוקת' }), pass).toHaveCount(0);
      await expect(client.getByText('צפייה בהצעת הגישור'), pass).toHaveCount(0);
    }
  });

  test('פרטי עסקה: "צפייה במחלוקת" פותח את לשונית המחלוקת @android #7be825aa', async ({ asUser }) => {
    test.skip(!dealId, 'нет сделки из предыдущего шага');
    const client = await asUser('client');
    await client.goto(`/deals/${dealId}`);
    await openTab(client, 'פרטי עסקה');
    await client.getByRole('button', { name: 'צפייה במחלוקת' }).click();
    await expect(client).toHaveURL(/tab=dispute/);
    await expect(client.getByText('מחלוקת עם גישור AI').first()).toBeVisible();
  });

  test('נותן שירות: כרטיס הסכמה לגישור AI — "אישור" ו"דחייה" @android #7da5215c', async ({ asUser }) => {
    test.skip(!dealId, 'нет сделки из предыдущего шага');
    const provider = await asUser('provider');
    await provider.goto(`/deals/${dealId}?tab=dispute`);
    await waitWithReload(provider, provider.getByText('האם את/ה מאשר גישור בעזרת AI?'));
    await expect(provider.getByRole('button', { name: 'אישור', exact: true })).toBeVisible();
    await expect(provider.getByRole('button', { name: 'דחייה', exact: true })).toBeVisible();
    await expect(provider.getByText('דחיית', { exact: true })).toHaveCount(0);
    await expect(provider.getByRole('button', { name: 'צפייה במחלוקת' })).toHaveCount(0);
  });

  test('הצעה מוכנה: "צפייה בהצעת הגישור" פותח /deals/proposal @android #7be825aa', async ({ asUser }) => {
    test.skip(!dealId, 'нет сделки из предыдущего шага');
    const client = await asUser('client');
    const provider = await asUser('provider');

    await provider.goto(`/deals/${dealId}?tab=dispute`);
    await provider.getByRole('button', { name: 'אישור', exact: true }).click();

    // Действие поставщика должно стать видно клиенту.
    await client.goto(`/deals/${dealId}?tab=dispute`);
    await waitWithReload(client, client.getByText('הצעת גישור מוכנה'), 120_000);
    await expect(client.getByText('צפייה בהצעת הגישור').first()).toBeVisible();

    await client.getByText('צפייה בהצעת הגישור').last().click();
    await expect(client).toHaveURL(/\/deals\/proposal/);
    await expect(client.getByText('הצעת גישור בעזרת AI').first()).toBeVisible();
    await expect(client.getByRole('button', { name: 'אישור ההצעה' })).toBeVisible();
    await expect(client.getByRole('button', { name: 'דחיית ההצעה' })).toBeVisible();
  });

  test('מחלוקת שהוכרעה: ביומן "המחלוקת הוכרעה" @android #45354c82', async ({ asUser }) => {
    test.skip(!dealId, 'нет сделки из предыдущего шага');
    const client = await asUser('client');
    const provider = await asUser('provider');

    for (const page of [client, provider]) {
      await page.goto(`/deals/${dealId}?tab=dispute`);
      await waitWithReload(page, page.getByText('צפייה בהצעת הגישור'));
      await page.getByText('צפייה בהצעת הגישור').last().click();
      await expect(page).toHaveURL(/\/deals\/proposal/);
      await page.getByRole('button', { name: 'אישור ההצעה' }).click();
      await expect(page.getByRole('button', { name: 'אישור ההצעה' })).toHaveCount(0, { timeout: 20_000 });
    }

    for (const [who, page] of [['client', client], ['provider', provider]] as const) {
      await page.goto(`/deals/${dealId}`);
      await openTab(page, 'היסטוריה');
      await waitWithReload(page, page.getByText('המחלוקת הוכרעה', { exact: true }));
      const entries = await historyEntries(page);
      expect(entries[0], who).toBe('המחלוקת הוכרעה');
      expect(entries[1], who).toMatch(TODAY_TIME);
      expect(entries.join('\n'), who).not.toContain('המחלוקת נסגרה ללא הכרעה');
    }
  });
});
